export interface ConnectorConfig {
  /** Slack bot token with chat:write scope */
  slackBotToken: string
  /** Slack channel ID (e.g., C0123456789) or name (e.g., #general) */
  slackChannel: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface CalendlyWebhookPayload {
  invitee: {
    name: string
    email: string
  }
  answers: Record<string, string>
}

export interface SlackPostMessageResponse {
  ok: boolean
  channel: string
  ts: string
  message: {
    text: string
    type: string
    subtype: string
    ts: string
  }
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): asserts payload is CalendlyWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.invitee || typeof p.invitee !== 'object') {
    throw new Error('Missing required field: invitee')
  }
  const invitee = p.invitee as Record<string, unknown>
  if (typeof invitee.name !== 'string' || !invitee.name.trim()) {
    throw new Error('Missing required field: invitee.name')
  }
  if (typeof invitee.email !== 'string' || !invitee.email.trim()) {
    throw new Error('Missing required field: invitee.email')
  }
  if (!p.answers || typeof p.answers !== 'object') {
    throw new Error('Missing required field: answers')
  }
}

function formatMessage(payload: CalendlyWebhookPayload): string {
  const lines = ['New meeting booked!']
  lines.push(`Name: ${payload.invitee.name}`)
  lines.push(`Email: ${payload.invitee.email}`)
  const answerEntries = Object.entries(payload.answers)
  if (answerEntries.length > 0) {
    const answersStr = answerEntries
      .map(([question, answer]) => `${question} -> ${answer}`)
      .join(', ')
    lines.push(`Answers: ${answersStr}`)
  } else {
    lines.push('Answers: (none)')
  }
  return lines.join('\n')
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const calendlyPayload = payload as CalendlyWebhookPayload

  const text = formatMessage(calendlyPayload)

  const fetchFn = getFetch(config)
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({
    channel: config.slackChannel,
    text,
  })

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} for POST ${url}`
    )
  }

  const data = (await response.json()) as SlackPostMessageResponse

  if (!data.ok) {
    throw new Error(`Slack API returned error: ${JSON.stringify(data)}`)
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
  }
}

