      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({
          ok: true,
          channel: 'C0123456789',
          ts: '1234567890.123456',
          message: {
            text: 'New meeting booked!\nName: Jane Doe\nEmail: jane.doe@example.com\nAnswers: What is your company? -> Acme Corp, How did you hear about us? -> Google Search',
            type: 'message',
            subtype: 'bot_message',
            ts: '1234567890.123456',
          },
        })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: CalendlyWebhookPayload = {
      invitee: { name: 'Jane Doe', email: 'jane.doe@example.com' },
      answers: {
        'What is your company?': 'Acme Corp',
        'How did you hear about us?': 'Google Search',
      },
