  it('includes Authorization header with Bearer token', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ ok: true, channel: 'C1', ts: '1', message: { text: '', type: '', subtype: '', ts: '' } }))

    await handle(
      {
        invitee: { name: 'Test', email: 'test@example.com' },
