    const { fetch, calls } = fakeFetch(() => jsonResponse({ ok: true, channel: 'C1', ts: '1', message: { text: '', type: '', subtype: '', ts: '' } }))

    await handle(
      {
        invitee: { name: 'Alice Smith', email: 'alice@example.com' },
        answers: { 'Question 1': 'Answer 1', 'Question 2': 'Answer 2' },
      },
      { slackBotToken: 'xoxb-token', slackChannel: 'C1', fetch }
