    expect(sentJson.text).toContain('Name: Alice Smith')
    expect(sentJson.text).toContain('Email: alice@example.com')
    expect(sentJson.text).toContain('Question 1 -> Answer 1')
    expect(sentJson.text).toContain('Question 2 -> Answer 2')
  })

